// Primary keys that are GLOBAL in the Cloud schema (not per tenant): collections.id, payments.id and bank_movements.id.
// The plan cannot see other tenants offline, so the apply step (prod:import, slice S5) MUST run these SELECT-only
// queries against the target right before executing the import, feed the summed counts to evaluateTarget as
// `collidingIds`, and refuse on any collision. students.id is generated by the database and cannot collide.
import { literal } from "./sql-literal.mjs";

export const COLLISION_TABLES = ["collections", "payments", "bank_movements"];
const IDS_PER_QUERY = 500;

/** { table: [ids] } of the transformed plan, in plan order. */
export const collisionIds = (tables) => Object.fromEntries(COLLISION_TABLES.map((t) => [t, tables[t].map((row) => row.id)]));

/** SELECT-only statements; the sum of their `n` is the number of plan ids that already exist anywhere. */
export function collisionQueries(tables) {
  return COLLISION_TABLES.flatMap((table) => {
    const ids = tables[table].map((row) => row.id);
    const queries = [];
    for (let i = 0; i < ids.length; i += IDS_PER_QUERY) {
      queries.push(`SELECT COUNT(*) AS n FROM ${table} WHERE id IN (${ids.slice(i, i + IDS_PER_QUERY).map(literal).join(", ")});`);
    }
    return queries;
  });
}
